/* QMES inventory register + Excel import: user-confirmed, never overwrite records. */
(function(){'use strict';
const root=document.getElementById('inventory');if(!root||root.dataset.importInstalled)return;root.dataset.importInstalled='1';
const table=root.querySelector('.namo-new-stock');if(!table)return;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=v=>String(v??'').trim(),qty=v=>Number(String(v??'').replace(/,/g,'').trim());
const header=table.querySelector('header>div:last-child');
const add=(label,id)=>{const b=document.createElement('button');b.type='button';b.id=id;b.textContent=label;header.prepend(b);return b;};
const excel=add('엑셀 불러오기','invExcel'),manual=add('+ 신규 재고등록','invManual');
manual.style.cssText=excel.style.cssText='background:#1469b7;color:#fff;border-color:#1469b7';
const modal=document.createElement('dialog');modal.id='invImportModal';modal.innerHTML='<section class="invPanel"><h2 id="invTitle">재고 등록</h2><p id="invHelp">원본 재고·LOT·입출고 이력은 삭제하거나 덮어쓰지 않습니다.</p><div id="invManualForm"><div class="invFields"><label>구분<select id="invCategory"><option value="RM">원자재</option><option value="PM">부자재</option><option value="WIP">중간배치</option><option value="FG">완제품</option></select></label><label>품목코드<input id="invCode"></label><label>품목명<input id="invName"></label><label>LOT NO<input id="invLot"></label><label>보관위치<input id="invLocation" placeholder="A-1-1"></label><label>수량(kg)<input id="invQty" type="number" min="0" step="0.001"></label><label>품질상태<select id="invStatus"><option value="AVAILABLE">사용가능</option><option value="IQC_PENDING">IQC 대기</option><option value="OQC_PENDING">OQC 대기</option><option value="HOLD">보류</option><option value="NONCONFORM">부적합</option></select></label><label>등록 사유<input id="invReason" placeholder="실사 입고 / 이관 등"></label></div></div><div id="invExcelForm" hidden><p>엑셀 첫 행에 <b>구분, 품목코드, 품목명, LOT NO, 보관위치, 수량(kg), 품질상태</b> 열을 입력하세요. 기존 재고에 합산할 신규 입고건만 등록합니다.</p><input id="invFile" type="file" accept=".xlsx,.xls,.csv"><div class="invPreview" id="invPreview"></div></div><p class="invMessage" id="invMessage" role="status"></p><footer><button type="button" id="invCancel">취소</button><button type="button" id="invCommit">등록 확정</button></footer></section>';root.append(modal);
const $=id=>modal.querySelector('#'+id);let mode='manual',pending=[],busy=false;
function show(type){mode=type;pending=[];$('invTitle').textContent=type==='excel'?'엑셀 일괄 재고등록':'신규 재고등록';$('invManualForm').hidden=type!=='manual';$('invExcelForm').hidden=type!=='excel';$('invMessage').textContent='';$('invPreview').innerHTML='';$('invCommit').disabled=false;modal.showModal();}
manual.onclick=()=>show('manual');excel.onclick=()=>show('excel');$('invCancel').onclick=()=>{if(!busy)modal.close();};
function normalize(x){return text(x).toUpperCase().replace(/\s+/g,'');}
function readRow(row){const alias={'구분':'category','재고구분':'category','category':'category','품목코드':'itemCode','품목 코드':'itemCode','itemcode':'itemCode','품목명':'itemName','원자재명':'itemName','itemname':'itemName','lotno':'lotNo','lot':'lotNo','lot번호':'lotNo','로트번호':'lotNo','보관위치':'locationCode','위치':'locationCode','location':'locationCode','현재고':'quantity','수량':'quantity','수량(kg)':'quantity','현재고(kg)':'quantity','quantity':'quantity','품질상태':'qualityStatus','상태':'qualityStatus','status':'qualityStatus','사유':'reason','비고':'reason'};
const result={};for(const [k,v] of Object.entries(row)){const key=normalize(k).toLowerCase().replace(/[^a-z0-9가-힣]/g,'');const canon=Object.entries(alias).find(([a])=>normalize(a).toLowerCase().replace(/[^a-z0-9가-힣]/g,'')===key);if(canon)result[canon[1]]=text(v);}
return result;}
function finalize(r){const kind={'원자재':'RM','원료':'RM','부자재':'PM','중간배치':'WIP','재공품':'WIP','완제품':'FG'},status={'사용가능':'AVAILABLE','가용':'AVAILABLE','IQC대기':'IQC_PENDING','OQC대기':'OQC_PENDING','보류':'HOLD','부적합':'NONCONFORM'};
return {category:kind[r.category]||normalize(r.category)||'RM',itemCode:normalize(r.itemCode),itemName:text(r.itemName),lotNo:normalize(r.lotNo),locationCode:normalize(r.locationCode),quantity:qty(r.quantity),qualityStatus:status[text(r.qualityStatus).replace(/\s+/g,'')]||normalize(r.qualityStatus)||'AVAILABLE',reason:text(r.reason)||'엑셀 재고 신규 입고'};}
async function loadSheet(){if(window.XLSX)return window.XLSX;const scripts=['https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js','https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js'];for(const url of scripts){try{await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=reject;document.head.append(s);});if(window.XLSX)return window.XLSX;}catch(e){}}throw Error('엑셀 읽기 라이브러리를 불러오지 못했습니다. 네트워크 상태를 확인하세요.');}
async function parseFile(file){const XLSX=await loadSheet(),buf=await file.arrayBuffer(),book=XLSX.read(buf,{type:'array',cellDates:false}),sheet=book.Sheets[book.SheetNames[0]];const raw=XLSX.utils.sheet_to_json(sheet,{defval:''});return raw.filter(x=>Object.values(x).some(v=>text(v)!=='')).map((x,i)=>({...finalize(readRow(x)),excelRow:i+2}));}
function issues(r){let a=[];if(!r.itemCode||!r.itemName||!r.lotNo||!r.locationCode)a.push('품목·LOT·위치 누락');if(!Number.isFinite(r.quantity)||r.quantity<=0)a.push('수량 오류');if(!['RM','PM','WIP','FG'].includes(r.category))a.push('구분 오류');if(!['AVAILABLE','IQC_PENDING','OQC_PENDING','HOLD','NONCONFORM'].includes(r.qualityStatus))a.push('상태 오류');if(r.lotNo.startsWith('HIST-'))a.push('이력 LOT 등록 금지');return a;}
$('invFile').onchange=async e=>{pending=[];$('invMessage').textContent='파일 읽는 중...';try{const file=e.target.files[0];if(!file)return;if(file.size>4*1024*1024)throw Error('4MB 이하 파일만 업로드 가능합니다.');pending=await parseFile(file);if(!pending.length)throw Error('등록할 데이터가 없습니다.');const keys=new Set();let failed=0;const display=pending.slice(0,300).map(r=>{const err=issues(r),key=[r.itemCode,r.lotNo,r.locationCode,r.qualityStatus].join('|');if(keys.has(key))err.push('파일 내 중복');keys.add(key);r.invalid=err.length>0;if(r.invalid)failed++;return '<tr><td>'+r.excelRow+'</td><td>'+esc(r.itemCode)+'</td><td>'+esc(r.lotNo)+'</td><td>'+esc(r.locationCode)+'</td><td>'+esc(r.quantity)+'</td><td>'+esc(err.join(', ')||'등록대상')+'</td></tr>';}).join('');if(pending.length>300)throw Error('한 번에 300행 이하로 나누어 업로드하세요.');$('invPreview').innerHTML='<table><thead><tr><th>행</th><th>품목</th><th>LOT</th><th>위치</th><th>kg</th><th>검사</th></tr></thead><tbody>'+display+'</tbody></table>';$('invMessage').textContent='총 '+pending.length+'행 중 입력 오류 '+failed+'행. 중복된 품목·LOT는 저장 전 다시 확인합니다.';}catch(e){pending=[];$('invMessage').textContent='파일 오류: '+e.message;}};
async function api(url,body){const response=await fetch(url,{credentials:'same-origin',method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await response.json().catch(()=>({}));if(!response.ok||result.success===false)throw Error(result.message||'저장 오류');return result;}
async function register(r){await api('/api/inventory/items',{itemCode:r.itemCode,itemName:r.itemName,category:r.category,unit:'kg'});await api('/api/inventory/transactions',{transactionType:'RECEIPT',itemCode:r.itemCode,itemName:r.itemName,category:r.category,lotNo:r.lotNo,quantity:r.quantity,toLocation:r.locationCode,toStatus:r.qualityStatus,reason:r.reason,referenceNo:'STOCK-EXCEL-20261020'});}
$('invCommit').onclick=async()=>{if(busy)return;let rows;if(mode==='manual'){rows=[finalize({category:$('invCategory').value,itemCode:$('invCode').value,itemName:$('invName').value,lotNo:$('invLot').value,locationCode:$('invLocation').value,quantity:$('invQty').value,qualityStatus:$('invStatus').value,reason:$('invReason').value})];}else rows=pending;
if(!rows.length){$('invMessage').textContent='등록할 데이터가 없습니다.';return;}
if(rows.some(r=>issues(r).length||r.invalid)){$('invMessage').textContent='오류 항목을 수정한 후 다시 업로드하세요.';return;}
if(!confirm(rows.length+'건을 신규 입고로 등록하시겠습니까? 기존 원장·LOT는 삭제하지 않습니다.'))return;
busy=true;$('invCommit').disabled=true;let done=0,failed=0;try{const resp=await fetch('/api/inventory/stock',{credentials:'same-origin',cache:'no-store'}),json=await resp.json();if(!resp.ok||json.success===false)throw Error('기존 재고 조회에 실패했습니다. 중복 검증을 완료할 수 없습니다.');const existing=json.data||[],seen=new Set(existing.map(r=>[normalize(r.item_code),normalize(r.lot_no),normalize(r.location_code),normalize(r.quality_status)].join('|')));const unique=[];for(const r of rows){const key=[r.itemCode,r.lotNo,r.locationCode,r.qualityStatus].join('|');if(seen.has(key)){failed++;continue;}unique.push(r);seen.add(key);}if(failed)$('invMessage').textContent='기존 동일 품목·LOT '+failed+'건 제외. 등록 진행 중...';for(const r of unique){try{await register(r);done++;$('invMessage').textContent=done+'건 등록 완료 / '+failed+'건 제외';}catch(e){failed++;$('invMessage').textContent=r.itemCode+' '+r.lotNo+': '+e.message+' ('+done+'건 완료)';break;}}
$('invMessage').textContent='신규 등록 '+done+'건, 제외/오류 '+failed+'건. 오류가 있으면 확인 후 다시 업로드하세요.';root.querySelector('#stockReload')?.click();}catch(e){$('invMessage').textContent=e.message;}finally{busy=false;$('invCommit').disabled=false;}};
var st=document.createElement('style');st.textContent='#inventory #invImportModal{width:min(900px,95vw);max-height:85vh;border:1px solid #ccdbea;border-radius:10px;padding:23px;color:#203e5a}#inventory .invPanel h2{margin-top:0}#inventory .invPanel p{font-size:12px;color:#62758a}#inventory .invFields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}#inventory .invFields label{font-size:12px;display:flex;flex-direction:column;gap:4px}#inventory .invFields input,#inventory .invFields select{padding:10px;border:1px solid #c5d6e6;border-radius:5px}#inventory .invPanel footer{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}#inventory .invPanel button{border:1px solid #c4d7e6;padding:9px 15px;border-radius:5px;cursor:pointer}#inventory #invCommit{background:#1469b7;color:white}#inventory .invMessage{color:#154b82!important}#inventory .invPreview{overflow:auto;max-height:300px}#inventory .invPreview table{border-collapse:collapse;width:100%;font-size:12px}#inventory .invPreview td,#inventory .invPreview th{border-bottom:1px solid #dce5ee;padding:7px}';document.head.append(st);
})();